const reviewTabs=[...document.querySelectorAll('[data-review-tab]')];
function selectReviewTab(next,focus=false){for(const tab of reviewTabs){const active=tab.dataset.reviewTab===next;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;$(tab.getAttribute('aria-controls')).hidden=!active;if(active&&focus)tab.focus();}document.body.dataset.reviewTab=next;$('review-actions').hidden=next==='revision';$('review-actions').open=false;$('review-plan-selection').hidden=next==='revision';if(view==='reviews'){placeContext();if(ready)render();}}
for(const [index,tab] of reviewTabs.entries()){tab.onclick=()=>selectReviewTab(tab.dataset.reviewTab);tab.onkeydown=e=>{let next;if(e.key==='ArrowRight'||e.key==='ArrowLeft')next=1-index;else if(e.key==='Home')next=0;else if(e.key==='End')next=1;if(next!==undefined){e.preventDefault();selectReviewTab(reviewTabs[next].dataset.reviewTab,true);}};}
function selectTask(kind,next,focus=false){
 const tabs=[...document.querySelectorAll(`button[role="tab"][data-${kind}-task]`)];if(!tabs.some(tab=>tab.getAttribute(`data-${kind}-task`)===next))return;
 for(const tab of tabs){const active=tab.getAttribute(`data-${kind}-task`)===next;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;$(tab.getAttribute('aria-controls')).hidden=!active;if(active&&focus)tab.focus();}
 if(kind==='analysis'){document.body.dataset.analysisTask=next;if(view==='data'){placeContext();render();}}else{document.body.dataset.diagnosticTask=next;if(view==='evaluation'){placeContext();if(ready)renderEvaluation();}}
}
for(const kind of ['analysis','diagnostic']){
 const tabs=[...document.querySelectorAll(`button[role="tab"][data-${kind}-task]`)];for(const [index,tab] of tabs.entries()){
  tab.onclick=()=>selectTask(kind,tab.getAttribute(`data-${kind}-task`));
  tab.onkeydown=e=>{const target=e.key==='Home'?0:e.key==='End'?tabs.length-1:e.key==='ArrowRight'?(index+1)%tabs.length:e.key==='ArrowLeft'?(index+tabs.length-1)%tabs.length:null;if(target===null)return;e.preventDefault();selectTask(kind,tabs[target].getAttribute(`data-${kind}-task`),true);};
 }
}
document.body.dataset.analysisTask='forecast';document.body.dataset.diagnosticTask='hourly';
const reviewTools=[...document.querySelectorAll('[data-review-tool]')];
function openReviewTool(next,focus=false){$('review-actions').open=false;for(const button of reviewTools){const active=button.dataset.reviewTool===next,pane=$(button.getAttribute('aria-controls'));pane.open=active;button.setAttribute('aria-expanded',String(active));button.classList.toggle('active',active);}if(focus&&!next)$('review-actions').querySelector('summary').focus();if(focus){const pane=reviewTools.find(b=>b.dataset.reviewTool===next);if(pane){const target=$(pane.getAttribute('aria-controls'));target.focus();target.scrollIntoView?.({block:'start'});}}}
$('review-verdict-evidence').onclick=()=>openReviewTool('evidence',true);
for(const button of reviewTools){button.onclick=()=>openReviewTool(button.getAttribute('aria-expanded')==='true'?null:button.dataset.reviewTool,true);const pane=$(button.getAttribute('aria-controls'));pane.addEventListener('toggle',()=>{if(pane.open&&button.getAttribute('aria-expanded')!=='true')openReviewTool(button.dataset.reviewTool);else if(!pane.open){button.setAttribute('aria-expanded','false');button.classList.remove('active');if(pane.contains(document.activeElement))$('review-actions').querySelector('summary').focus();}});}
