function kpis(id,values){$(id).replaceChildren(...values.map(([label,value,detail=''])=>{const box=document.createElement('div');box.className='kpi';for(const [cls,v]of[['label',label],['value',value],['detail',detail]]){const el=document.createElement('div');el.className=cls;el.textContent=v;box.append(el);}return box;}));}
function facts(id,rows){const dl=document.createElement('dl');for(const[label,value]of rows){const pair=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');pair.className='fact';dt.textContent=label;dd.textContent=value;pair.append(dt,dd);dl.append(pair);}$(id).replaceChildren(dl);}
function table(id,headers,rows){const t=document.createElement('table'),thead=t.createTHead(),head=thead.insertRow();headers.forEach(x=>{const th=document.createElement('th');th.scope='col';th.textContent=x;head.append(th);});const body=t.createTBody();for(const row of rows){const tr=body.insertRow();row.forEach(value=>{const td=tr.insertCell();if(value instanceof Node)td.append(value);else{td.textContent=value??'—';if(/^[+−-]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?%?$/.test(String(value??'')))td.classList.add('number');}});}$(id).replaceChildren(t);}
