async function start(){
 try{
  const responses=await Promise.all(['data.json','manifest.json','research.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw Error(`Retained ${url} unavailable`);return r.arrayBuffer();}));
  text('workspace-load-detail','Verifying reference');
  [data,manifest,research]=responses.map(bytes=>JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes)));
  sourceHashes={data_sha256:await sha256(responses[0]),research_sha256:await sha256(responses[2])};
  if(sourceHashes.data_sha256!==manifest.data_sha256)throw Error('Dataset identity does not match its manifest');
  retainedSourceFiles={};for(const [index,name] of ['data','manifest'].entries()){const raw=new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(responses[index]);retainedSourceFiles[name]={name:name+'.json',text:raw,sha256:await sha256(responses[index])};}
  canonical=canonicalRows(data);for(const d of data.days)$('date').add(new Option(d.date,d.date));
  $('date').value='2026-07-15';for(const id of['tank','compare-a','compare-b','frontier-daily-tank'])for(const cap of data.tanks)$(id).add(new Option(fmt(cap,0)+' m³',String(cap)));
  $('tank').value='4000';$('compare-a').value='1000';$('compare-b').value='4000';ready=true;document.body.dataset.ready='true';$('workspace-loader').hidden=true;
  for(const id of['date','tank','download','plan-source'])$(id).disabled=false;awaitingData.forEach(el=>el.disabled=false);
  route(location.hash.slice(1),false);
 }catch(e){
  ready=false;document.body.dataset.ready='failed';$('workspace-loader').hidden=true;$('status').classList.remove('review-context-status');
  awaitingData.forEach(el=>el.disabled=true);for(const id of['date','tank','download','plan-source'])$(id).disabled=true;
  text('status',`Workspace could not load: ${e.message}. Reload to retry.`);document.querySelectorAll('.view:not(#view-pilot) .unavailable').forEach(el=>el.hidden=false);render();
 }
}
