function renderCandidateComparison(){
 if(!scheduleHandoff?.candidate){text('candidate-comparison','Import a scheduler handoff in Data to compare it with its exact matched reference.');return;}
 const c=scheduleHandoff.candidate,d=data.days.find(d=>d.date===c.date),ref=d.schedules[String(c.tankCapacityM3)].totals,t=c.plan.totals;
 table('candidate-comparison',['Metric','Imported candidate','Frozen reference','Flat control'],[
 ['Matched case',`${c.date} / ${c.tankCapacityM3} m³`,`${c.date} / ${c.tankCapacityM3} m³`,`${c.date} / ${c.tankCapacityM3} m³`],
 ['Scenario cost €',fmt(t.cost_eur,2),fmt(ref.cost_eur,2),fmt(ref.baseline_cost_eur,2)],['Water m³',fmt(t.water_produced_m3,0),fmt(ref.water_produced_m3,0),fmt(ref.water_demand_m3,0)],
 ['Energy kWh',fmt(t.energy_kwh,0),fmt(ref.energy_kwh,0),fmt(ref.baseline_energy_kwh,0)],['Minimum tank m³',fmt(t.min_storage_m3,0),fmt(ref.min_storage_m3,0),fmt(c.tankCapacityM3*.5,0)],
 ['End tank m³',fmt(t.final_storage_m3,0),fmt(ref.final_storage_m3,0),fmt(c.tankCapacityM3*.5,0)],['Source',scheduleIdentity.name,'Retained reference','Constant 120 m³/h']]);
 const p=document.createElement('p');p.className='micro';p.textContent='Candidate method and decision timing are not certified here. Cost comparisons use retained clock tariffs.';$('candidate-comparison').append(p);
}
